<?php
require_once dirname(__DIR__) . '/middleware/bootstrap.php';
require_role('admin');
$db=Database::connection();$filters=['status'=>(string)($_GET['status']??''),'course'=>(string)($_GET['course']??''),'term'=>(string)($_GET['term']??'')];$service=new ReportService($db);$export=($_GET['export']??'')==='csv';$rows=$service->registrations($filters+['export'=>$export]);
if($export){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="course-registration-report-'.date('Ymd-His').'.csv"');$out=fopen('php://output','w');fputcsv($out,['Registration ID','Student','Register number','Department','Course code','Course title','Credits','Academic term','Status','Requested at','Decision note']);foreach($rows as $r){$values=[(string)$r['id'],$r['full_name'],$r['register_number'],$r['department'],$r['code'],$r['title'],(string)$r['credits'],$r['term_name'],$r['status'],$r['requested_at'],$r['decision_note']??''];foreach($values as &$v){if(preg_match('/^[=+\-@\t\r]/',(string)$v))$v="'".$v;}unset($v);fputcsv($out,$values);}fclose($out);exit;}
$courses=$db->query('SELECT id,code,title FROM courses ORDER BY code')->fetchAll();$terms=$db->query('SELECT id,name FROM academic_terms ORDER BY starts_on DESC')->fetchAll();$availability=$db->query("SELECT c.code,c.title,c.capacity,COALESCE(SUM(r.status IN ('pending','approved')),0) enrolled FROM courses c LEFT JOIN registrations r ON r.course_id=c.id AND r.term_id=(SELECT id FROM academic_terms WHERE is_current=1 LIMIT 1) WHERE c.active=1 GROUP BY c.id ORDER BY enrolled DESC")->fetchAll();
page_start('Enrollment reports','admin/reports.php');
?>
<div class="content-width"><?php page_title('Enrollment reports','Analyze course capacity and export filtered registration records.'); ?>
<div class="panel mb-4"><form class="row g-3 align-items-end"><div class="col-md-4"><label class="form-label">Course</label><select class="form-select" name="course"><option value="">All courses</option><?php foreach($courses as $c): ?><option value="<?= (int)$c['id'] ?>" <?= $filters['course']==$c['id']?'selected':'' ?>><?= e($c['code'].' · '.$c['title']) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Term</label><select class="form-select" name="term"><option value="">All terms</option><?php foreach($terms as $t): ?><option value="<?= (int)$t['id'] ?>" <?= $filters['term']==$t['id']?'selected':'' ?>><?= e($t['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Status</label><select class="form-select" name="status"><option value="">All statuses</option><?php foreach(['pending','approved','rejected','cancelled'] as $s): ?><option value="<?= $s ?>" <?= $filters['status']===$s?'selected':'' ?>><?= ucfirst($s) ?></option><?php endforeach; ?></select></div><div class="col-md-2 d-grid"><button class="btn btn-primary">Filter</button></div></form></div>
<div class="panel mb-4 p-0 overflow-hidden"><div class="d-flex justify-content-between align-items-center p-3"><h2 class="h5 fw-bold mb-0">Course availability (current term)</h2></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Course</th><th>Enrolled / Capacity</th><th>Seats available</th><th>Fill</th></tr></thead><tbody><?php foreach($availability as $a): $seats=max(0,(int)$a['capacity']-(int)$a['enrolled']);$pct=(int)$a['capacity']?min(100,round((int)$a['enrolled']/(int)$a['capacity']*100)):0; ?><tr><td><?= e($a['code'].' · '.$a['title']) ?></td><td><?= (int)$a['enrolled'] ?> / <?= (int)$a['capacity'] ?></td><td><?= $seats ?></td><td><div class="progress" role="progressbar" aria-valuenow="<?= $pct ?>" aria-valuemin="0" aria-valuemax="100"><div class="progress-bar" style="width:<?= $pct ?>%"><?= $pct ?>%</div></div></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 fw-bold">Registration records <span class="text-muted fw-normal">(<?= count($rows) ?><?= count($rows)===500?' shown (limit 500)':'' ?>)</span></h2><?php $query=http_build_query(array_filter($filters,static fn($v)=>$v!=='')); ?><a class="btn btn-outline-primary" href="<?= e(url('admin/reports.php?'.$query.($query?'&':'').'export=csv')) ?>"><i class="bi bi-download me-1"></i>Export CSV</a></div>
<div class="panel p-0 overflow-hidden"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Student</th><th>Course</th><th>Term</th><th>Status</th><th>Requested</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['full_name']) ?><div class="small text-muted"><?= e($r['register_number']) ?></div></td><td><?= e($r['code'].' · '.$r['title']) ?></td><td><?= e($r['term_name']) ?></td><td><?= status_badge($r['status']) ?></td><td><?= e(date('M j, Y',strtotime($r['requested_at']))) ?></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="5"><div class="empty-state"><h3>No matching records</h3></div></td></tr><?php endif; ?></tbody></table></div></div></div>
<?php page_end(); ?>
